SELECT USER_ID, USER_EMAIL, EMAIL_VERIFIED
FROM TB_USER
WHERE EMAIL_AUTH_CODE = #{emailAuthCode}
AND USER_EMAIL = #{userEmail}
AND EMAIL_AUTH_EXPIRE > SYSDATE
